(()=>{const out={};for(const property of ['-webkit-animation','-webkit-transition']){out[property]={};for(const value of ['none','auto','initial','opacity 1s ease','slide 2s linear','Spin 1000ms ease-in 200ms 2 alternate both paused','opacity 250ms ease-in 50ms allow-discrete','opacity 1s, transform 2s linear','spin 1s infinite, fade 2s reverse','-1s','1s -2s','1s 2s 3s','"Slide" 1s','2s steps(3, end) spin','2s cubic-bezier(0.1, 0.2, 0.3, 1) spin','none, opacity 1s','inherit 1s','auto auto','1s linear linear','bogus bogus bogus']){const s=document.createElement('div').style;s.setProperty(property,value);out[property][value]={text:s.cssText,value:s.getPropertyValue(property),supported:CSS.supports(property,value),components:Array.from({length:s.length},(_,i)=>[s.item(i),s.getPropertyValue(s.item(i))])};}}return out})()
